import{_ as p,a0 as u,w as a,s as r,ao as l,I as t,x as s,a1 as o,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"如何在 Ubuntu/Debian Linux 上編寫、編譯和運行一個 C 程序 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu/Debian Linux 上編寫、編譯和運行一個 C 程序 | LCTT (202012) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu/Debian Linux 上編寫、編譯和運行一個 C 程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu/Debian Linux 上編寫、編譯和運行一個 C 程序 | LCTT (202012) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202012/20201118 How to Write, Compile and Run a C Program in Ubuntu and Other Linux Distributions -Beginner-s Tip","title":"如何在 Ubuntu/Debian Linux 上編寫、編譯和運行一個 C 程序","tag":"202012","desc":""},"relativePath":"202012/20201118 How to Write, Compile and Run a C Program in Ubuntu and Other Linux Distributions -Beginner-s Tip.md","filePath":"[post].md"}'),d={name:"202012/20201118 How to Write, Compile and Run a C Program in Ubuntu and Other Linux Distributions -Beginner-s Tip.md"};function g(C,i,m,b,f,k){const n=u("Link");return a(),r("div",null,[i[32]||(i[32]=l('<h1 id="如何在-ubuntu-debian-linux-上編寫、編譯和運行一個-c-程序" tabindex="-1">如何在 Ubuntu/Debian Linux 上編寫、編譯和運行一個 C 程序 <a class="header-anchor" href="#如何在-ubuntu-debian-linux-上編寫、編譯和運行一個-c-程序" aria-label="Permalink to “如何在 Ubuntu/Debian Linux 上編寫、編譯和運行一個 C 程序”">​</a></h1><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2020/11/Run-C-Program-Linux.png?resize=800%2C450&amp;ssl=1" alt=""></p><p>你是如何在 Linux 上使用 C 編寫你的程序的？它確實是非常簡單的，由三個簡單的步驟組成。</p><p><strong>步驟 1</strong>: 編寫你的 C 程序，並使用一個 <code>.c</code> 的擴展名進行保存。例如，<code>my_program.c</code> 。</p><p><strong>步驟 2</strong>: 在一個終端中使用 <code>gcc</code> 編譯器來編譯程序並生成目標文件，像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gcc -o my_program my_program.c</span></span></code></pre></div><p><strong>步驟 3</strong>: 在 Linux 中，你可以以運行生成的對象文件的方式來運行你的 C 程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>./my_program</span></span></code></pre></div><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2020/11/running-c-program-linux.png?resize=795%2C399&amp;ssl=1" alt=""></p><p>這只是如何在 Linux 中編譯和運行 C 程序的簡要總結。假設你是 C 語言或 Linux 系統的新手，我將仔細演示這些步驟，以便你能在 Linux 環境中舒服地編寫 C 程序。</p><p>事實上，我將討論如何在 Linux 終端中以及在代碼編輯器中運行 C 程序的兩種方式。</p><h3 id="方法-1-在-linux-終端中運行-c-程序" tabindex="-1">方法 1: 在 Linux 終端中運行 C 程序 <a class="header-anchor" href="#方法-1-在-linux-終端中運行-c-程序" aria-label="Permalink to “方法 1: 在 Linux 終端中運行 C 程序”">​</a></h3>',12)),t("p",null,[i[2]||(i[2]=s("為了在 Linux 中運行一個 C 程序，你需要在你的系統上有一個 C 編譯器。最流行的編譯器是 ",-1)),i[3]||(i[3]=t("code",null,"gcc",-1)),i[4]||(i[4]=s("（",-1)),t("ruby",null,[o(n,{href:"https://gcc.gnu.org/"},{default:e(()=>[...i[0]||(i[0]=[s("GNU 編譯器套件",-1)])]),_:1}),i[1]||(i[1]=t("rt",null,"GNU Compiler Collection",-1))]),i[5]||(i[5]=s("）。",-1))]),i[33]||(i[33]=l('<p>你可以使用你發行版的軟件包管理器來安裝 <code>gcc</code> 。在基於 Debian 和 Ubuntu 的 Linux 發行版中，使用 <code>apt</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install gcc</span></span></code></pre></div><p>切換到保存你的 C 程序的目錄（或者提供路徑），然後通過編譯程序生成對象文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gcc -o my_program my_program.c</span></span></code></pre></div><p>記住，提供輸出對象文件（<code>-o my_program</code>）是可選的。如果你不提供，那麼將自動生成一個名稱為 <code>a.out</code> 的對象文件。但是這樣並不好，因為編譯每個 C 程序都會覆蓋它，而且你也不知道這個 <code>a.out</code> 對象文件究竟屬於哪個程序。</p><p>在你的對象文件生成後，運行它來運行 C 程序。它已經能夠執行了。像這樣簡單地使用它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>./my_program</span></span></code></pre></div>',7)),t("p",null,[i[7]||(i[7]=s("接下來，如果你的程序是正確的，它將顯示出你所期望的輸出。正如你所看到的，這和 ",-1)),o(n,{href:"https://itsfoss.com/c-plus-plus-ubuntu/"},{default:e(()=>[...i[6]||(i[6]=[s("在 Linux 中運行 C++ 程序",-1)])]),_:1}),i[8]||(i[8]=s(" 沒什麼不同。",-1))]),i[34]||(i[34]=t("p",null,[t("em",null,"每更改一次你的程序，你都必須先重新編譯它，然後再次運行生成的對象文件來運行這個新的 C 程序。")],-1)),i[35]||(i[35]=t("h3",{id:"方法-2-如何在-linux-中使用一個諸如-vscode-之類的代碼編輯器來運行-c-程序",tabindex:"-1"},[s("方法 2: 如何在 Linux 中使用一個諸如 VSCode 之類的代碼編輯器來運行 C 程序 "),t("a",{class:"header-anchor",href:"#方法-2-如何在-linux-中使用一個諸如-vscode-之類的代碼編輯器來運行-c-程序","aria-label":"Permalink to “方法 2: 如何在 Linux 中使用一個諸如 VSCode 之類的代碼編輯器來運行 C 程序”"},"​")],-1)),i[36]||(i[36]=t("p",null,"並不是每一個人都能適應命令列和終端，我完全理解這一點。",-1)),i[37]||(i[37]=t("p",null,"你可以使用一個諸如 Eclipse 或 Code Blocks 之類的真正的 C/C++ IDE ，但是它們是很重量級的程序，通常更適合於大型的項目。",-1)),i[38]||(i[38]=t("p",null,"我建議使用一個開源的代碼編輯器，像 VSCode 或 Atom 。它們基本上是文本編輯器，但是你可以通過安裝附加組件來直接在圖形化的代碼編輯器中編譯和運行程序。",-1)),t("p",null,[i[11]||(i[11]=s("在這個示例中，我使用 ",-1)),o(n,{href:"https://code.visualstudio.com"},{default:e(()=>[...i[9]||(i[9]=[s("VSCode",-1)])]),_:1}),i[12]||(i[12]=s(" 編輯器。它是一個來自微軟的 ",-1)),o(n,{href:"https://itsfoss.com/best-modern-open-source-code-editors-for-linux/"},{default:e(()=>[...i[10]||(i[10]=[s("非常流行的開源的代碼編輯器",-1)])]),_:1}),i[13]||(i[13]=s(" 。",-1))]),t("p",null,[i[15]||(i[15]=s("首先，在 Ubuntu 的 ",-1)),o(n,{href:"https://itsfoss.com/install-visual-studio-code-ubuntu/"},{default:e(()=>[...i[14]||(i[14]=[s("軟件中心中安裝 VSCode",-1)])]),_:1}),i[16]||(i[16]=s(" 。對於其它發行版來説，請檢查你的 Linux 發行版的軟件包管理器或軟件中心。你可以參看它的官方網站來查看更多的信息。",-1))]),i[39]||(i[39]=l('<p>啓動 VSCode ，打開或創建一個工程，在這裏創建你的 C 程序。我使用一個簡單的 Hello World 程序作為示例。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2020/11/c-program-visual-studio-code-linux.png?resize=800%2C441&amp;ssl=1" alt=""></p><p>你必須確保你已經在你的 Linux 系統上安裝了 <code>gcc</code> 編譯器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install gcc</span></span></code></pre></div><p>接下來你要做的事是使用一個允許你運行 C 代碼的擴展。微軟可能會提示你安裝它的 C/C++ 程序擴展，但它的設置很複雜，因此我不推薦。</p><p>相反，我建議你使用 Code Runner 擴展。它是一個簡單直接的擴展，你可以在不使用額外配置的情況下輕鬆地運行 C 和 C++ 代碼。</p><p>轉到擴展標籤頁，在其中搜索和安裝 “Code Runner” 。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2020/11/running-c-program-in-linux-with-visual-studio-code.png?resize=800%2C500&amp;ssl=1" alt="安裝 Code Runner 擴展來運行 C/C++ 程序"></p><p>重新啓動 VSCode 。現在，你能夠使用下面方法中的其中一個來運行 C 代碼：</p><ul><li>使用快捷鍵 <code>Ctrl+Alt+N</code> 。</li><li>按下 <code>F1</code> ，接下來選擇或輸入 “Run Code” 。</li><li>在文本編輯器中右鍵單擊，從上下文菜單中單擊 “Run code” 。</li></ul><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2020/11/running-c-program-in-linux-with-visual-studio-code.jpg?resize=800%2C500&amp;ssl=1" alt="右鍵單擊程序文件，然後選擇 Run Code"></p><p>當你運行這個 C 程序時，它將會被自動編譯和運行。你可以在編輯器底部打開的終端中看到輸出。還有比這更好的事情嗎？</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2020/11/run-c-program-in-linux-with-visual-studio-code.jpg?resize=800%2C500&amp;ssl=1" alt="程序輸出顯示在編輯器的底部"></p><p>你更喜歡哪一種方法？</p><p>在 Linux 命令列中運行一些 C 程序是沒有問題的，但是使用一個代碼編輯器會更容易一些，而且會節省時間。你不覺得嗎？</p><p>你可以自己決定想使用哪一種方法。</p><hr>',17)),t("p",null,[i[18]||(i[18]=s("via: ",-1)),o(n,{href:"https://itsfoss.com/run-c-program-linux/"},{default:e(()=>[...i[17]||(i[17]=[s("https://itsfoss.com/run-c-program-linux/",-1)])]),_:1})]),t("p",null,[i[23]||(i[23]=s("作者：",-1)),o(n,{href:"https://itsfoss.com/author/abhishek/"},{default:e(()=>[...i[19]||(i[19]=[s("Abhishek Prakash",-1)])]),_:1}),i[24]||(i[24]=s(" 選題：",-1)),o(n,{href:"https://github.com/lujun9972"},{default:e(()=>[...i[20]||(i[20]=[s("lujun9972",-1)])]),_:1}),i[25]||(i[25]=s(" 譯者：",-1)),o(n,{href:"https://github.com/robsean"},{default:e(()=>[...i[21]||(i[21]=[s("robsean",-1)])]),_:1}),i[26]||(i[26]=s(" 校對：",-1)),o(n,{href:"https://github.com/wxy"},{default:e(()=>[...i[22]||(i[22]=[s("wxy",-1)])]),_:1})]),t("p",null,[i[29]||(i[29]=s("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...i[27]||(i[27]=[s("LCTT",-1)])]),_:1}),i[30]||(i[30]=s(" 原創編譯，",-1)),o(n,{href:"https://linux.cn/"},{default:e(()=>[...i[28]||(i[28]=[s("Linux中國",-1)])]),_:1}),i[31]||(i[31]=s(" 榮譽推出",-1))])])}const L=p(d,[["render",g]]);export{T as __pageData,L as default};
